import{_ as s,c as i,o as e,b0 as t}from"./chunks/framework.Becqh7-x.js";const l="/linux-dev-docs/assets/image-20260115094727154.DNbKVawx.png",n="/linux-dev-docs/assets/image-20230729132141751.DLafWb4k.png",r="data:image/png;base64,",p="/linux-dev-docs/assets/image-20260115095454150.BsQtPLyQ.png",h="/linux-dev-docs/assets/image-20260115095544294.gAytntlR.png",d="/linux-dev-docs/assets/image-20260115095706134.rQRqnZPY.png",k="/linux-dev-docs/assets/image-20260115095809174.Bxb_S3Rq.png",c="/linux-dev-docs/assets/image-20260115095848661.Cgr5tnuF.png",o="/linux-dev-docs/assets/image-20260115100002702.CmVf2G78.png",u="/linux-dev-docs/assets/image-20260115100148043.Lc5w_Hqt.png",A="/linux-dev-docs/assets/image-20230729135201594.2Tsy0vXb.png",g="/linux-dev-docs/assets/image-20260115100235095.D1LjeSrV.png",y=JSON.parse('{"title":"LV050-imx6ull的uart配置","description":null,"frontmatter":{"title":"LV050-imx6ull的uart配置","date":"2026-01-14T16:29:02.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/bare/uart/126d2ce864d6013d55d3e47e","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-14T16:29:02.019Z","fulluuid":"d55d3e47e8b9443ea27bf2a7102e0d55","useduuid":"d55d3e47e"}},"headers":[],"relativePath":"sdoc/bare/uart/126d2ce864d6013d55d3e47e.md","filePath":"sdoc/25-裸机开发/20-串口通信/LV050-imx6ull的uart配置.md","lastUpdated":1768604092000}'),R={name:"sdoc/bare/uart/126d2ce864d6013d55d3e47e.md"};function _(T,a,C,U,m,b){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="lv050-imx6ull的uart配置" tabindex="-1">LV050-imx6ull的uart配置 <a class="header-anchor" href="#lv050-imx6ull的uart配置" aria-label="Permalink to &quot;LV050-imx6ull的uart配置&quot;">​</a></h1><h2 id="一、硬件原理分析" tabindex="-1">一、硬件原理分析 <a class="header-anchor" href="#一、硬件原理分析" aria-label="Permalink to &quot;一、硬件原理分析&quot;">​</a></h2><h3 id="_1-原理图" tabindex="-1">1. 原理图 <a class="header-anchor" href="#_1-原理图" aria-label="Permalink to &quot;1. 原理图&quot;">​</a></h3><p>我使用的是正点原子的 ALPHA 开发板，原理图如下：</p><p><img src="'+l+'" alt="image-20260115094727154"></p><p>可以看到，我们需要使用的是串口 1，也就是 UART1。</p><h3 id="_2-开发板连接" tabindex="-1">2. 开发板连接 <a class="header-anchor" href="#_2-开发板连接" aria-label="Permalink to &quot;2. 开发板连接&quot;">​</a></h3><p>我们还需要用 USB 串口线将串口 1 和电脑连接起来，并且还需要设置 JP5 跳线帽，将串口 1 的 RXD、 TXD 两个引脚分别与 P116、 P117 连接一起，如图所示：</p><img src="'+n+'" alt="image-20230729132141751" style="zoom:50%;"><h2 id="二、寄存器配置" tabindex="-1">二、寄存器配置 <a class="header-anchor" href="#二、寄存器配置" aria-label="Permalink to &quot;二、寄存器配置&quot;">​</a></h2><h3 id="_1-配置并使能-uart1-时钟" tabindex="-1">1. 配置并使能 UART1 时钟 <a class="header-anchor" href="#_1-配置并使能-uart1-时钟" aria-label="Permalink to &quot;1. 配置并使能 UART1 时钟&quot;">​</a></h3><h4 id="_1-1-配置-uart-模块的时钟-寄存器-ccm-cscdr1" tabindex="-1">1.1 配置 UART 模块的时钟（寄存器： CCM_CSCDR1） <a class="header-anchor" href="#_1-1-配置-uart-模块的时钟-寄存器-ccm-cscdr1" aria-label="Permalink to &quot;1.1 配置 UART 模块的时钟（寄存器： CCM_CSCDR1）&quot;">​</a></h4><p>配置并使能 UART1 时钟，参考资料：《i.MX 6ULL Applications ProcessorReference Manual》参考手册的《 Chapter 18: ClockController Module (CCM)》。 （下图来自参考手册的 Figure 18-3. Clock Tree - Part 2 ）</p><p><img src="'+r+'" alt="image-20260115095344111"></p><p>根据上图，我们需要配置 CCM_CSCDR1 [UART_CLK_SEL] 和 CCM_CSCDR1 [UART_CLK_PODF] 两个位：</p><p><img src="'+p+'" alt="image-20260115095454150"></p><p>由上图 CCM_CSCDR1 寄存器，我们可以了解到 CCM_CSCDR1 [UART_CLK_SEL] 默认值（图中 Reset 对应的值）为 0； CCM_CSCDR1 [UART_CLK_PODF] 默认值为 0。我们一般选择 pll3_80m 作为 UART 的时钟源， UART_CLK_PODF 分频系数选 1 分频（不分频），最后得到 UART 的时钟频率为 80MHz。</p><p><img src="'+h+'" alt="image-20260115095544294"></p><p>正好默认值都为 0 满足我们的时钟需求，所以后续的编程实验，串口时钟这部分可以不设置，用默认值就可以了。</p><h4 id="_1-2-使能-uart-模块的时钟-寄存器-ccm-ccgr5" tabindex="-1">1.2 使能 UART 模块的时钟（寄存器： CCM_CCGR5） <a class="header-anchor" href="#_1-2-使能-uart-模块的时钟-寄存器-ccm-ccgr5" aria-label="Permalink to &quot;1.2 使能 UART 模块的时钟（寄存器： CCM_CCGR5）&quot;">​</a></h4><p><img src="'+d+'" alt="image-20260115095706134"></p><p>由上图 CCM_CCGR5 寄存器，我们可以了解到 CCM_CCGR5 [CG12] 的默认值为 11。我们知道 11 表示该模块全程使能，使用默认值，无需设置。</p><h3 id="_2-复用相关-gpio-为-uart1-功能" tabindex="-1">2. 复用相关 GPIO 为 UART1 功能 <a class="header-anchor" href="#_2-复用相关-gpio-为-uart1-功能" aria-label="Permalink to &quot;2. 复用相关 GPIO 为 UART1 功能&quot;">​</a></h3><h4 id="_2-1-配置-uart1-tx-复用功能" tabindex="-1">2.1 配置 UART1_TX 复用功能 <a class="header-anchor" href="#_2-1-配置-uart1-tx-复用功能" aria-label="Permalink to &quot;2.1 配置 UART1_TX 复用功能&quot;">​</a></h4><p>可以参考《i.MX 6ULL Applications ProcessorReference Manual》参考手册的 32.6.17 SW_MUX_CTL_PAD_UART1_TX_DATA SW MUX Control Register (IOMUXC_SW_MUX_CTL_PAD_UART1_TX_DATA) 用到的寄存器为 IOMUXC_SW_MUX_CTL_PAD_UART1_TX_DATA。</p><p><img src="'+k+'" alt="image-20260115095809174"></p><p>由上图我们得知 IOMUXC_SW_MUX_CTL_PAD_UART1_TX_DATA [MUX_MODE] 的默认值为 0101，因此我们需要将其改为 0，用于 UART_TX 功能。</p><h4 id="_2-2-配置-uart1-rx-复用功能" tabindex="-1">2.2 配置 UART1_RX 复用功能 <a class="header-anchor" href="#_2-2-配置-uart1-rx-复用功能" aria-label="Permalink to &quot;2.2 配置 UART1_RX 复用功能&quot;">​</a></h4><p>可以参考《i.MX 6ULL Applications ProcessorReference Manual》参考手册的 32.6.18 SW_MUX_CTL_PAD_UART1_RX_DATA SW MUX Control Register (IOMUXC_SW_MUX_CTL_PAD_UART1_RX_DATA) 用到的寄存器为 IOMUXC_SW_MUX_CTL_PAD_UART1_RX_DATA。</p><p><img src="'+c+'" alt="image-20260115095848661"></p><p>由上图我们得知 IOMUXC_SW_MUX_CTL_PAD_UART1_RX_DATA [MUX_MODE] 的默认值为 0101，因此我们需要将其改为 0，用于 UART_RX 功能。</p><h4 id="_2-3-选择引脚" tabindex="-1">2.3 选择引脚 <a class="header-anchor" href="#_2-3-选择引脚" aria-label="Permalink to &quot;2.3 选择引脚&quot;">​</a></h4><p>IMX6ULL 中，可能会有多个引脚都可以驱动某个模块，还需要进一步选择。比如下图（参考手册 32.3.3 Daisy chain - multi pads driving same module input pin）中： A、 B、 C 三个引脚都可以设置为工作于 Module X，它们都可以驱动 Module X。但是使用哪一个引脚呢？还需要设置“ Daisy Chain select”，</p><p><img src="'+o+'" alt="image-20260115100002702"></p><p>对 于 UART1_RX 引 脚 ， 我们除 设置 IOMUXC_SW_MUX_CTL_PAD_UART1_RX_DATA 让它工作于 ALT0 之外，还需要设置寄存器 IOMUXC_UART1_RX_DATA_SELECT_INPUT，可以参考《i.MX 6ULL Applications ProcessorReference Manual》参考手册的 32.6.360 UART1_RX_DATA_SELECT_INPUT DAISY Register(IOMUXC_UART1_RX_DATA_SELECT_INPUT)</p><p><img src="'+u+'" alt="image-20260115100148043"></p><p>在上图中，引脚 GPIO1_IO02 设置为 ALT8 模式时，它也可以用作 UART1 的 RX 输入引脚；引脚 UART1_RX 设置为 ALT0 模式时，它也可以用作 UART1 的 RX 输入引脚。UART1_RX 为何可以选择那么多引脚？</p><img src="'+A+'" alt="image-20230729135201594" style="zoom:50%;"><p>UART1 的发送引脚有 2 个选择： GPIO1_IO02、 UART1_TX，假设选择了 UART1_TX 作为发送引脚。UART1 的接收引脚有 2 个选择： GPIO1_IO03、 UART1_RX，假设选择了 UART1_RX 作为接收引脚。</p><p>但是 UART1 的模块还可能通过 daisy 引脚再次选择： GPIO1_IO02、GPIO1_IO03、 UART1_TX、 UART1_RX 中的某一个。比如上图中，选择 UART1_TX 时，这就构成了回环，可以用于测试： IMX6ULL 发出去的数据直接返回给自己；选择 UART_RX 是，就可以接收外面设备比如 PC 机的数据。</p><h4 id="_2-4-配置-uart1-tx-硬件参数" tabindex="-1">2.4 配置 UART1_TX 硬件参数 <a class="header-anchor" href="#_2-4-配置-uart1-tx-硬件参数" aria-label="Permalink to &quot;2.4 配置 UART1_TX 硬件参数&quot;">​</a></h4><p>寄存器： IOMUXC_SW_PAD_CTL_PAD_UART1_TX_DATA。经过比对，我们使用默认值（ 0x10b0）即可，无需配置。</p><h4 id="_2-5-配置-uart1-rx-硬件参数" tabindex="-1">2.5 配置 UART1_RX 硬件参数 <a class="header-anchor" href="#_2-5-配置-uart1-rx-硬件参数" aria-label="Permalink to &quot;2.5 配置 UART1_RX 硬件参数&quot;">​</a></h4><p>寄存器： IOMUXC_SW_PAD_CTL_PAD_UART1_RX_DATA。经过比对，我们使用默认值（ 0x10b0）即可，无需配置。</p><h3 id="_3-设置-uart1-传输格式-波特率" tabindex="-1">3. 设置 UART1 传输格式，波特率 <a class="header-anchor" href="#_3-设置-uart1-传输格式-波特率" aria-label="Permalink to &quot;3. 设置 UART1 传输格式，波特率&quot;">​</a></h3><h4 id="_3-1-配置寄存器-uart1-ucr2-0x2020084" tabindex="-1">3.1 配置寄存器 UART1_UCR2（0x2020084） <a class="header-anchor" href="#_3-1-配置寄存器-uart1-ucr2-0x2020084" aria-label="Permalink to &quot;3.1 配置寄存器 UART1_UCR2（0x2020084）&quot;">​</a></h4><p>设置 UART1 传输格式 ：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UART1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UCR2 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">14</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>bit[14]: 1，忽略 RTS 引脚</p><p>bit[8] : 0，关闭奇偶校验 默认为 0，无需设置</p><p>bit[6] : 0，停止位 1 位 默认为 0，无需设置</p><p>bit[5] : 1，数据长度 8 位</p><p>bit[2] : 1，发送数据使能</p><p>bit[1]: 1，接收数据使能</p><h4 id="_3-2-配置寄存器-uart1-ucr3-0x2020088" tabindex="-1">3.2 配置寄存器 UART1_UCR3（0x2020088） <a class="header-anchor" href="#_3-2-配置寄存器-uart1-ucr3-0x2020088" aria-label="Permalink to &quot;3.2 配置寄存器 UART1_UCR3（0x2020088）&quot;">​</a></h4><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UART1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UCR3 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_3-3-寄存器-uart1-ufcr-0x2020090" tabindex="-1">3.3 寄存器 UART1_UFCR（0x2020090） <a class="header-anchor" href="#_3-3-寄存器-uart1-ufcr-0x2020090" aria-label="Permalink to &quot;3.3 寄存器 UART1_UFCR（0x2020090）&quot;">​</a></h4><p>UART1_UFCR [9-7]： UART 的时钟源分频系数，我们选择 101（即十进制的 5），表示不分频。</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UART1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UFCR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /* Uart 的时钟 clk： 80MHz */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_3-4-寄存器-uart1-ubir-0x20200a4-和-uart1-ubmr-0x20200a8" tabindex="-1">3.4 寄存器 UART1_UBIR（0x20200A4）和 UART1_UBMR（0x20200A8） <a class="header-anchor" href="#_3-4-寄存器-uart1-ubir-0x20200a4-和-uart1-ubmr-0x20200a8" aria-label="Permalink to &quot;3.4 寄存器 UART1_UBIR（0x20200A4）和 UART1_UBMR（0x20200A8）&quot;">​</a></h4><p>通过设置 UART1_UBIR 与 UART1_UBMR，最终确定波特率。</p><p><img src="'+g+`" alt="image-20260115100235095"></p><p>（1）设置 115200 的波特率即 BaudRate = 115200；</p><p>（2）UART1 的时钟频率前面内容已确定 80Mhz 即 Ref Freq = 80000000；</p><p>（3）IMX6ULL 波特率计算公式得 115200 = 80000000 /(16*(UBMR +1)/(UBIR+1))；</p><p>（4）选取一组满足上式的参数： UBMR、 UBIR 即可；</p><p>（5）UART1_UBIR = 71 ； UART1_UBMR = 3124</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UART1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UBIR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 71</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UART1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UBMR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3124</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_4-使能-uart1" tabindex="-1">4. 使能 UART1 <a class="header-anchor" href="#_4-使能-uart1" aria-label="Permalink to &quot;4. 使能 UART1&quot;">​</a></h3><p>使能 UART1， 需要配置的是 UART1_UCR1(0x2020080)寄存器。配置 UART1_UCR1[0]： 1 表示使能 UART， 0 表示关闭 UART。</p><h2 id="三、实现串口的收发" tabindex="-1">三、实现串口的收发 <a class="header-anchor" href="#三、实现串口的收发" aria-label="Permalink to &quot;三、实现串口的收发&quot;">​</a></h2><p>这里就具体直接看 gitee 仓库吧：<a href="https://gitee.com/linux-dev-org/imx6ull-bare-demo/tree/main/02_UART" target="_blank" rel="noreferrer">02_UART · sumumm/imx6ull-bare-demo</a>。里边有几点修改需要说明一下，主要是对 Makefile 文件的修改：</p><p>（1）makefile 添加了数学库：Makefile 文件在链接的时候加入了数学库， 因为在 bsp_uart.c 中有个函数 uart_setbaudrate，在此函数中使用到了除法运算，因此在链接的时候需要将编译器的数学库也链接进来。一般的交叉工具链里都提示有基本的数学运算，它们位于 libgcc.a 中。我们需要把 libgcc.a 也链接进程序里，所以就需要修改 Makefile。</p><p>（2）makefile 编译选项：加入了选项“-fno-builtin”，否则编译的时候提示“putc”、“puts”这两个函数与内建函数冲突，错误信息如下所示：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">warning:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> conflicting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> types</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> for</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> built-in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> function</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ‘putc’</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">warning:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> conflicting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> types</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> for</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> built-in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> function</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ‘puts’</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>在编译的时候加入选项“-fno-builtin”表示不使用内建函数，这样我们就可以自己实现 putc 和 puts 这样的函数了。</p>`,76)])])}const F=s(R,[["render",_]]);export{y as __pageData,F as default};
